import {readSavedState} from './saved-state.mjs?v=blackline-5';
import {ARENA_API_URL} from './auth-config.mjs?v=blackline-2';
import {renderSyntony, renderMissionContext, renderRealWorldDebrief, renderPracticeNote, renderAssuranceQuestion, realWorldHandoff} from './syntony.js';
import {arenaAuth,mountAuthPanel} from './auth.mjs?v=blackline-7';
import {CAMPAIGNS, createRun, evaluateAttack, applyGovernance, replay, nextLevel, answerChallenge, retryLevel} from './engine.js?v=blackline-5';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roster = [
{id:'cipher',name:'Cipher',alias:'THE ARCHITECT',color:'#a4e3bd',lens:'Boundary map',clue:'Separate the request, the evidence, and the authority to act. A plausible instruction is not an authorization.'},
{id:'aegis',name:'Aegis',alias:'THE AUDITOR',color:'#e4a78c',lens:'Decision audit',clue:'Trace who owns the decision. A control should specify an accountable owner, a permitted action, and a condition for retesting.'},
{id:'trace',name:'Trace',alias:'THE NAVIGATOR',color:'#99bfff',lens:'Signal map',clue:'Follow the signal across sources. Repetition and polished presentation cannot make an unverified claim independent evidence.'},
{id:'relay',name:'Relay',alias:'THE COURIER',color:'#d4dedf',lens:'Workflow trace',clue:'Track where an input becomes a tool action. Preserve the useful path while placing a gate at the trust boundary.'},
{id:'null',name:'Null',alias:'THE SPECIALIST',color:'#c2a2f6',lens:'Scope check',clue:'Find the smallest control that contains this failure. A global shutdown may move the damage into the review queue.'},
{id:'bastion',name:'Bastion',alias:'THE SENTINEL',color:'#83d8ce',lens:'Authority scan',clue:'A message claiming senior authority still needs verification through a trusted channel. Check the source of the permission.'},
{id:'sigil',name:'Sigil',alias:'THE INTERPRETER',color:'#eaff65',lens:'Intent lens',clue:'Compare what the source says with the action the system proposes. Quoted instructions and data should not silently become policy.'},
{id:'glitch',name:'Glitch',alias:'THE MAVERICK',color:'#fc9a95',lens:'Counterclaim',clue:'Challenge the apparent consensus. Ask which assumption would collapse if every supporting claim came from the same source.'},
{id:'root',name:'Root',alias:'THE DIVER',color:'#82e8ee',lens:'Provenance dive',clue:'Trace every consequential claim to its origin. A generated summary may erase uncertainty without adding any new evidence.'}
];
let mode='game', modelId='cipher', run=null, attackDraft=null, controlDraft=null, lensOpen=false, busy=false, audioOn=false, audioContext, drone, droneGain, storageWarning=false;
const STORE='blackline-v2';
let attackDraftText='',draftAudit='',probeAvailable=false;
const workbenches={};
const newWorkbench=()=>({draft:null,journal:[],results:{}});
let workbench=newWorkbench();
function rememberWorkbench(){if(run){workbench.draft={level:run.level,attempt:run.attempt,attackId:attackDraft,text:attackDraftText.slice(0,1200)};workbenches[run.campaignId]=workbench;}}
function appendEvidence(target,entry){target.journal=[...target.journal.slice(-199),entry];}
function clearCurrentProbeResults(){if(run){delete workbench.results[`${run.level}:before`];delete workbench.results[`${run.level}:after`];}}
function matchingProbe(stage){
  const result=workbench.results[`${run.level}:${stage}`];
  return result&&result.attempt===run.attempt&&result.attackId===(run.selectedAttack||attackDraft)
    &&result.payload===attackDraftText.trim()&&(stage!=='after'||result.controlId===run.selectedControl)?result:null;
}
function payloadChecklist(text){
  const checks=[["Claim of authority",/approv|authoriz|verified|waiv|override|priority|urgenc|exception|certif/i],["Requested downstream action",/send|export|change|issue|release|publish|reroute|mark|treat|skip|bypass|classif|cancel|disclos|transfer|clear|freeze|pay|recommen/i],["Untrusted source artifact",/document|note|record|invoice|report|submission|certificate|email|file|brief|ledger|source|log|roster|bulletin|policy|summary/i]];
  return checks.map(([label,re])=>(re.test(text)?"✓ ":"◇ ")+label).join(" · ")+" · Writing cues only, not an exploit verdict.";
}
function attackWorkbench(){
  if(!attackDraft)return '<div class="attack-workbench"><div class="eyebrow">RED-TEAM WORKBENCH</div><p>Select an attack route to open an editable adversarial payload.</p></div>';
  return `<section class="attack-workbench"><div class="eyebrow">RED-TEAM WORKBENCH / AUTHOR YOUR ATTACK</div><h3>Turn the threat hypothesis into a payload.</h3><p>Revise the example into your own fictional untrusted note, document, or tool-facing message. The local mission score is based on the selected scenario route, not on arbitrary wording.</p><label for="attack-payload">UNTRUSTED SOURCE TEXT · 20–1,200 CHARACTERS</label><textarea id="attack-payload" rows="5" maxlength="1200" spellcheck="false" ${busy?'disabled':''}>${esc(attackDraftText)}</textarea><div class="workbench-actions"><button class="text-button" data-action="audit-payload">INSPECT ATTACK HYPOTHESIS ↗</button><button class="text-button" data-action="reset-payload">RESTORE EXAMPLE ↻</button></div>${draftAudit?`<p class="workbench-audit">${esc(draftAudit)}</p>`:""}${probePanel("before")}<small>Use only fictional or public data. Workbench drafts and probe evidence stay in this tab; export before reloading or signing in. Exports retain the latest 200 entries per campaign. Game outcomes are simulated.</small></section>`;
}
function probePanel(stage){
  const result=matchingProbe(stage);
  return `<section class="probe-panel"><div class="eyebrow">OPENAI / LIVE FICTIONAL AGENT PROBE</div><p>${stage==="before"?"Test the authored payload with a hosted OpenAI model playing a fictional agent.":"Replay the same authored input with your governance control included."} No real-world tools are connected and model output never changes the game score.</p>${probeAvailable?`<button class="text-button" data-action="probe" data-stage="${stage}" ${busy?'disabled':''}>${stage==="after"?"RETEST WITH OPENAI ↻":"TEST WITH OPENAI ↗"}</button>`:"<small>Hosted OpenAI probing is not yet connected. The deterministic mission remains playable.</small>"}${result?`<div class="probe-result"><b>${esc(result.boundary.toUpperCase())} · ${esc(result.model)}</b><p><strong>Fictional agent:</strong> ${esc(result.agentResponse)}</p><p><strong>Proposed tool intent:</strong> ${esc(result.toolIntent)}</p><p><strong>Model assessment:</strong> ${esc(result.reason)}</p><small>Model-generated assessment, not independent evidence of an exploit. No tools executed.</small></div>`:""}</section>`;
}
async function refreshProbeAvailability(){
  if(typeof ARENA_API_URL==='undefined'||!ARENA_API_URL)return;
  try{
    const r=await fetch(`${new URL(ARENA_API_URL).origin}/api/config`,{headers:{Accept:"application/json"},cache:"no-store"});
    const data=await r.json();probeAvailable=data?.blacklineProbe?.available===true;
    if(run)render();
  }catch{probeAvailable=false;}
}
async function runModelProbe(stage){
  if(!probeAvailable)throw new Error("Hosted OpenAI testing is not yet connected.");
  if(!arenaAuth.require())return;
  if(!run||!['before','after'].includes(stage)||run.phase!==(stage==='before'?'evaluate':'assure'))throw new Error('This probe is not available at the current mission phase.');
  const payload=attackDraftText.trim();
  if(payload.length<20||payload.length>1200)throw new Error("Write a fictional payload of 20–1,200 characters first.");
  const attack=level().attacks.find(a=>a.id===(run.selectedAttack||attackDraft));
  if(!attack)throw new Error("Select an attack route first.");
  const context={campaignId:run.campaignId,level:run.level,attempt:run.attempt,stage,attackId:attack.id,payload,
    controlId:stage==='after'?run.selectedControl:null,controlName:stage==='after'?(level().controls.find(c=>c.id===run.selectedControl)?.name||''):''};
  const target=workbench;
  rememberWorkbench();
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);
  busy=true;render();
  try{
    const r=await fetch(`${new URL(ARENA_API_URL).origin}/api/blackline/probe`,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json",...arenaAuth.headers()},body:JSON.stringify({campaignId:context.campaignId,level:context.level,attackId:context.attackId,attackText:payload,stage,controlName:context.controlName}),credentials:"omit",redirect:"error",cache:"no-store",signal:controller.signal});
    const result=await r.json();
    if(!r.ok)throw new Error(result?.error?.message||"The OpenAI probe could not complete.");
    if(!result||!["held","crossed","unclear"].includes(result.boundary)||typeof result.agentResponse!=="string")throw new Error("Unsupported model response.");
    const entry={type:"openai-fictional-agent-probe",...context,level:context.level+1,model:String(result.model||"OpenAI").slice(0,100),boundary:result.boundary,agentResponse:String(result.agentResponse).slice(0,1400),toolIntent:String(result.toolIntent||"").slice(0,800),reason:String(result.reason||"").slice(0,1400),runId:String(result.runId||"").slice(0,100),simulated:true};
    target.results[`${context.level}:${stage}`]=entry;appendEvidence(target,entry);
    announce("OpenAI probe recorded. No external action executed.");
  }finally{clearTimeout(timer);busy=false;render();}
}

const SIGN_IN_SAVE_NOTICE='Sign-in is paused because your browser could not save your campaign. Your progress is still held in this tab; keep it open until saving works again.';
let saved={},saveNotice='';
try{const loaded=readSavedState(localStorage.getItem(STORE),roster.map(m=>m.id));saved=loaded.saved;modelId=saved.modelId;if(loaded.rejected.length)saveNotice='Some saved progress could not be read safely. Other valid campaigns are preserved; start a new run for the affected stream.';}catch{saved={};storageWarning=true;}
const character=()=>roster.find(x=>x.id===modelId);
const campaign=()=>CAMPAIGNS[run.campaignId];
const level=()=>campaign().levels[run.level];
function persist(){rememberWorkbench();saved.mode=mode;saved.modelId=modelId;if(run)saved[run.campaignId]={run,modelId};try{localStorage.setItem(STORE,JSON.stringify(saved));storageWarning=false;if(saveNotice===SIGN_IN_SAVE_NOTICE)saveNotice='';return true;}catch{storageWarning=true;return false;}}

function announce(message){$('#announcer').textContent=message;}
function stageScroll(){window.scrollTo({top:0,behavior:'instant'});}
function number(n){return String(n).padStart(2,'0');}
function avatar(m,cls=''){const i=roster.findIndex(x=>x.id===m.id);return `<div class="operator-portrait ${cls}" style="--px:${(i%3)*50}%;--py:${Math.floor(i/3)*50}%;--operator:${m.color}" aria-hidden="true"></div>`;}
function render(){document.body.classList.toggle('mission-mode',!!run);$('#app').innerHTML=run?(run.phase==='completed'?renderComplete():renderMission()):renderHome();}
function renderHome(){return `${saveNotice?`<p class="save-recovery" role="status">${esc(saveNotice)}</p>`:""}<section class="hero "><div class="hero-copy"><div class="eyebrow">SYNTONY CLOSE THE LOOP / A RED TEAMING GAME</div><h1>BREAK THE MODEL.<br><em>SAVE THE SYSTEM.</em></h1><p>A city runs on intelligence. Yours.<br>Become an AI-security operator. Expose the failure. Own the response. Keep the world running.</p><div class="hero-actions"><button class="primary" data-action="enter">PLAY THE GAME <span class="arrow">↗</span></button><a class="text-button" href="#syntony">MEET SYNTONY ↗</a></div><p class="hero-attribution">Human-led expertise + software for the real decisions behind AI.</p><div class="mode-note">9 CHARACTERS · 2 CAMPAIGNS · YOUR DECISIONS CARRY FORWARD</div></div><div class="hero-bottom"><div class="stat-row"><div><strong>09</strong><small>PLAYABLE<br>OPERATORS</small></div><div><strong>20</strong><small>ESCALATING<br>MISSIONS</small></div><div><strong>01</strong><small>CONTINUOUS<br>LOOP</small></div></div><div class="scene-label"><strong>MERIDIAN / 2089</strong><br>THE SYSTEM IS ONLY AS STRONG<br>AS ITS NEXT DECISION.</div></div></section>
<section class="models" id="models"><div class="section-head"><div><div class="eyebrow">01 / SELECT YOUR OPERATOR</div><h2>Nine minds. Your call.</h2></div><p>ANY OPERATOR. EITHER CAMPAIGN.</p></div><div class="roster">${roster.map((m,i)=>`<button class="operator ${m.id===modelId?'selected':''}" data-action="select-model" data-model="${m.id}" aria-pressed="${m.id===modelId}" style="--operator:${m.color}">${avatar(m)}<span class="operator-id">${number(i+1)}</span><div class="operator-label"><strong>${m.name}</strong><small>${m.alias}</small></div></button>`).join('')}</div><div class="character-brief"><div><span class="micro">OPERATOR SELECTED</span><h3>${character().name} <span>${character().alias}</span></h3></div><p><b>${character().lens}</b> · ${character().clue}</p><span class="badge">BOTH CAMPAIGNS AVAILABLE</span></div><p class="simulation-note">Nine original AI-security operators. Two fictional crisis campaigns. Every level must be beaten to unlock the next; each operator offers a different investigative lens.</p>
<div class="section-head campaign-head"><div><div class="eyebrow">02 / SELECT YOUR CAMPAIGN</div><h2>Different worlds. Rising stakes.</h2></div><p>10 LEVELS PER STREAM</p></div><div class="stream-grid">${streamCard('atlas')}${streamCard('prism')}</div></section>
<section class="loop-strip"><div class="loop-item"><span>01</span><div><h3>EVALUATE</h3><p>Expose a failure. Preserve the evidence.</p></div></div><div class="loop-item"><span>02</span><div><h3>GOVERN</h3><p>Assign an owner. Make a control decision.</p></div></div><div class="loop-item"><span>03</span><div><h3>ASSURE</h3><p>Replay the attack. Keep useful work alive.</p></div></div></section>${renderSyntony()}<section class="github-strip"><div><div class="eyebrow">OPEN THE SYSTEM</div><h2>Your next challenge starts with a fork.</h2><p>Inspect the scoring, build a mission, or connect your own governed pipeline. The game and Close the Loop toolkit are open source.</p></div><div class="github-links"><a href="https://github.com/Syntony-Research/close-the-loop/tree/main/game" target="_blank" rel="noopener noreferrer">EXPLORE THE CODE ↗</a><a href="https://github.com/Syntony-Research/close-the-loop/fork" target="_blank" rel="noopener noreferrer">FORK ON GITHUB ↗</a></div></section>`;}
function streamCard(id){const c=CAMPAIGNS[id],existing=saved[id]?.run;const business=id==='atlas';return `<article class="stream-card ${id}"><div class="stream-heading"><span class="micro">${business?'STREAM 01 / BUSINESS':'STREAM 02 / GOVERNMENT'}</span><span class="stream-symbol">${business?'⌁':'⌘'}</span></div><h3>${business?'THE CAPITAL CASCADE':'THE SOVEREIGN SIGNAL'}</h3><p>${business?'From a poisoned supplier request to a cascading infrastructure crisis. Defend the decisions that keep an economy moving.':'From a corrupted brief to a national emergency. Keep evidence, authority, and public trust from breaking apart.'}</p><div class="stream-tags"><span>${business?'FINANCE · SUPPLY CHAINS · INFRASTRUCTURE':'INTELLIGENCE · PUBLIC SERVICES · CRISIS RESPONSE'}</span><span>10 LEVELS</span></div><button class="primary" data-action="start" data-campaign="${id}">ENTER ${business?'BUSINESS':'GOVERNMENT'} STREAM <span class="arrow">→</span></button>${existing?`<button class="resume-button" data-action="resume" data-campaign="${id}">${existing.phase==='completed'?'VIEW CAMPAIGN DEBRIEF':'RESUME LEVEL '+number(existing.level+1)} ↗</button>`:''}</article>`;}
function phaseNav(){const p=['evaluate','govern','assure'].indexOf(run.phase);return `<div class="phase-nav" aria-label="Evaluation pipeline">${[['Evaluate','Expose the failure'],['Govern','Own the response'],['Assure','Replay the consequence']].map((a,i)=>`<div class="phase-step ${i===p?'active':''} ${i<p||p===-1?'finished':''}"><span class="phase-num">${i<p||p===-1?'✓':number(i+1)}</span><div><strong>${a[0]}</strong><small>${a[1]}</small></div></div>`).join('')}</div>`;}
function renderMission(){const c=campaign(),l=level(),m=character();return `<div class="game"><div class="game-top"><div class="mission-title">${avatar(m,'mini-portrait')}<div><div class="micro">${m.name.toUpperCase()} / ${run.campaignId==='atlas'?'BUSINESS':'GOVERNMENT'} STREAM / LEVEL ${number(run.level+1)} OF 10</div><h1>${esc(l.title)}</h1></div></div><div class="mission-score"><div class="micro">CAMPAIGN SCORE</div><strong>${esc(run.score)}</strong><span>/ 1,000</span></div></div><div class="game-toolbar"><span class="micro">IMMERSIVE GAME MODE · SYNTHETIC SCENARIO</span><button data-action="home">CHARACTERS & CAMPAIGNS</button></div><div class="game-layout"><aside class="campaign-map"><div class="panel"><div class="panel-title">CAMPAIGN MAP <span>10 NODES</span></div><div class="level-list">${c.levels.map((x,i)=>`<div class="level-row ${i===run.level?'current':''} ${i<run.level?'done':''}" title="Level ${i+1}: ${esc(x.title)}" ${i===run.level?'aria-current="step"':''}><span class="num">${i<run.level?'✓':number(i+1)}</span><div><b>${esc(x.title)}</b><small>${i<run.level?'loop closed':i===run.level?'active mission':'locked'}</small></div></div>`).join('')}</div></div><div class="panel sidebar-bottom"><div class="micro">EVIDENCE LOCKER</div><button data-action="export">↓ EXPORT EVIDENCE PACK</button><button data-action="how">↗ FIELD MANUAL</button></div>${renderPracticeNote(run.phase)}</aside><div class="mission-main">${phaseNav()}${storageWarning?'<p class="storage-note">Local saving is unavailable in this browser. Export your evidence to keep it.</p>':''}<section class="panel mission-brief"><span class="tag">${esc(l.district)} / ${esc(l.challenge.tier)}</span><h2>${esc(l.stakes)}</h2><p>${esc(l.brief)}</p><p class="objective"><b>YOUR OBJECTIVE</b>${esc(l.objective)}</p>${renderMissionContext(run.campaignId,run.level)}<div class="win-condition"><b>TO UNLOCK LEVEL ${run.level===9?'COMPLETE':number(run.level+2)}</b><span>Reproduce the failure · contain all 3 variants · keep ≥80% of useful work${l.challenge.fields.length?` · solve ${l.challenge.fields.length} decision checks`:""}.</span><small>Attempt ${esc(run.attempt || 1)} · Failed attempts do not unlock levels or add points.</small></div></section><section class="panel play-area" aria-label="Mission interaction">${renderPhase()}</section></div><aside class="telemetry"><section class="panel"><div class="panel-title">SYSTEM STATE <span>PERSISTENT</span></div><div class="meter-group">${meter('Continuity',run.metrics.continuity)}${meter('Public trust',run.metrics.trust)}${meter('Risk exposure',run.metrics.exposure,true)}${meter('Review backlog',run.metrics.review,true)}</div><div class="metric-note">Successful decisions carry forward. If a mission fails, retry restores this level’s checkpoint.</div></section><section class="panel evidence-panel"><div class="panel-title">SOURCE INTELLIGENCE <span>${number(l.evidence.length)}</span></div>${l.evidence.map(e=>`<article class="evidence-item"><h3>${esc(e.source)}</h3><p>${esc(e.text)}</p><span class="evidence-tag">${esc(e.trust)}</span></article>`).join('')}<button class="lens" data-action="lens" aria-expanded="${lensOpen}">◇ ${m.name.toUpperCase()} / ${m.lens.toUpperCase()} ${lensOpen?'−':'+'}</button><button class="mobile-intel text-button" data-action="return-mission">RETURN TO MISSION ↑</button>${lensOpen?`<div class="lens-detail"><b>${esc(m.clue)}</b><p>MISSION BOUNDARY: ${esc(l.boundary)}</p></div>`:''}</section></aside></div></div>`;}
function meter(label,n,inverse=false){return `<div class="meter ${inverse?'inverse':''}"><div class="meter-line"><span>${label}</span><strong>${Math.round(n)}<small> /100</small></strong></div><div class="meter-track" role="meter" aria-label="${label}" aria-valuenow="${esc(n)}" aria-valuemin="0" aria-valuemax="100"><div class="meter-fill" style="width:${Math.max(0,Math.min(100,n))}%"></div></div></div>`;}
function trace(){const f=run.finding;return `<div class="finding ${f.successful?'':'safe'}"><b>${f.successful?'FAILURE REPRODUCED':'BOUNDARY HELD'}</b><br>${esc(f.summary)}</div><div class="terminal"><div class="terminal-head">CAPTURED TRACE / SYNTHETIC RUN</div>${f.trace.map((x,i)=>`<p style="animation-delay:${i*.08}s">${esc(x)}</p>`).join('')}</div>`;}
function renderPhase(){const l=level();if(run.phase==='evaluate')return `<div class="eyebrow">01 / EVALUATE</div><h2>Find the point of failure.</h2><p class="step-intro">Inspect the source intelligence. Choose the adversarial test that exposes this mission’s trust boundary. ${run.level<2?'<b>Training hint: look for external text claiming permission to take a consequential action. Urgency and repetition alone cannot grant authority.</b>':'You must reproduce a consequential failure to pass.'}</p><button class="mobile-intel text-button" data-action="evidence-jump">INSPECT SOURCE INTELLIGENCE ↓</button>${run.level>0?`<div class="run-notice">Inherited state: <b>${Math.round(run.metrics.continuity)}% continuity</b> · <b>${Math.round(run.metrics.review)} review backlog</b>. Your earlier decisions are still in the system.</div>`:''}<div class="choice-list">${l.attacks.map((a,i)=>`<button class="choice ${attackDraft===a.id?'selected':''}" data-action="attack" data-id="${esc(a.id)}" aria-pressed="${attackDraft===a.id}"><span class="choice-num">${number(i+1)}</span><div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p>${attackDraft===a.id?`<small>TEST INPUT: ${esc(a.payload)}</small>`:''}</div></button>`).join('')}</div>${attackWorkbench()}<div class="action-bottom"><div class="micro">SYNTHETIC INPUT<br>NO LIVE SYSTEM ACCESS</div><button class="primary" data-action="evaluate" ${!attackDraft||busy?'disabled':''}>RUN ADVERSARIAL TEST <span class="arrow">→</span></button></div>`;
if(run.phase==='govern')return `<div class="eyebrow">02 / GOVERN</div><h2>A finding needs an owner.</h2>${trace()}${attackDraftText?`<div class="attack-workbench"><div class="eyebrow">OPERATOR-AUTHORED PAYLOAD</div><p class="operator-payload">${esc(attackDraftText)}</p><small>Operator hypothesis, not a verified exploit. The following outcome is from a deterministic simulation.</small></div>`:""}<p class="step-intro">Choose a response. Containment, service continuity, and human review all count. The decision becomes part of your evidence record.</p><div class="choice-list">${l.controls.map((c,i)=>`<button class="choice ${controlDraft===c.id?'selected':''}" data-action="control" data-id="${esc(c.id)}" aria-pressed="${controlDraft===c.id}"><span class="choice-num">${number(i+1)}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p>${run.level<4?`<small>ACCOUNTABLE OWNER: ${esc(c.owner)}</small>`:""}${controlDraft===c.id?`<small>TRADEOFF: ${esc(c.cost)}</small>`:''}</div></button>`).join('')}</div><div class="action-bottom"><div class="micro">FINDING → OWNER<br>CONTROL → DECISION</div><button class="primary" data-action="govern" ${!controlDraft||busy?'disabled':''}>COMMIT GOVERNANCE DECISION <span class="arrow">→</span></button></div>`;
if(run.phase==='assure'){const g=run.governance;const ctrl=l.controls.find(x=>x.id===run.selectedControl);return `<div class="eyebrow">03 / ASSURE</div><h2>Prove the response works.</h2><p class="step-intro">The control is in place. Replay the original attack, test three variants, and check that legitimate work can continue.</p><div class="decision-grid"><div><label>Accountable owner</label><p>${run.level>=4?'Assign the owner in the decision console below.':esc(g.owner)}</p></div><div><label>Deployment decision</label><p>${esc(g.decision)}</p></div><div><label>Control selected</label><p>${esc(ctrl?.name||g.summary)}</p></div><div><label>Rationale</label><p>${esc(ctrl?.rationale||g.summary)}</p></div></div><ul class="variants">${l.variants.map((v,i)=>`<li><span>${number(i+1)} /</span>${esc(v)}</li>`).join('')}</ul><p class="step-intro"><b>Assurance rule:</b> A changed source, control, authority, or dependency reopens the loop.</p>${renderChallenge()}${attackDraftText?probePanel("after"):""}<button class="primary replay-button" data-action="replay" ${busy?'disabled':''}>${busy?'REPLAYING THE CONSEQUENCES…':'REPLAY ATTACK + TEST CONTINUITY'} <span class="arrow">↻</span></button>`;}
const r=run.result;return `<div class="eyebrow">MISSION ${number(run.level+1)} / ${r.passed?'BEATEN · LOOP CLOSED':'FAILED · NEXT LEVEL LOCKED'}</div><div class="results-header"><h2>${r.passed?'BOUNDARY RESTORED.':'THE LOOP IS STILL OPEN.'}</h2><div class="score-orb"><strong>${esc(r.score)}</strong><small>OF 100 POINTS</small></div></div><p class="step-intro">${esc(r.summary)}</p><div class="result-stats"><div><strong>${esc(r.blocked)} / 3</strong><small>VARIANTS BLOCKED</small></div><div><strong>${esc(r.useful)}%</strong><small>USEFUL WORK KEPT</small></div><div><strong>${esc(run.score)}</strong><small>CAMPAIGN TOTAL</small></div></div><div class="pass-checks">${r.criteria.map(c=>`<div class="pass-check ${c.passed?'passed':'failed'}"><b>${c.passed?'✓':'×'} ${esc(c.label)}</b>${!c.passed?`<p>${esc(c.explanation)}</p>`:''}</div>`).join('')}</div><div class="lesson"><b>THE GOVERNANCE LESSON</b>${esc(r.lesson)}</div>${renderRealWorldDebrief(run.campaignId,run.level)}<div class="decision-grid"><div><label>Next retest</label><p>${esc(r.retest)}</p></div><div><label>Persistent consequence</label><p>${Object.entries(r.metricDeltas||{}).map(([k,v])=>`${esc(k)}: ${v>0?'+':''}${v}`).join(' · ')}</p></div></div><div class="action-bottom"><button class="text-button" data-action="export">EXPORT EVIDENCE ↓</button><button class="primary" data-action="${r.passed?'next':'retry'}">${!r.passed?'RETRY FROM CHECKPOINT':run.level===9?'VIEW CAMPAIGN DEBRIEF':'CONTINUE TO LEVEL '+number(run.level+2)} <span class="arrow">→</span></button></div>`;
}
function renderChallenge(){
  const c=level().challenge;
  if(!c.fields.length)return `<div class="training-note"><b>GUIDED ASSURANCE</b><p>This training level checks the original failure, all three variants, and useful-work continuity. Later missions put source, owner, release, and pipeline decisions in your hands.</p></div>`;
  return `<section class="decision-console"><div class="eyebrow">${esc(c.tier)} / DECISION CONSOLE</div><h3>Close every gap.</h3><p>Read the source intelligence before committing. Every check must be correct to unlock the next level.</p>${c.fields.map((f,i)=>{const selected=run.answers?.[f.key]||[];return `<fieldset class="decision-field"><legend><span>${number(i+1)}</span> ${esc(f.question)}</legend>${f.kind==='order'?`<ol class="pipeline-order">${selected.length?selected.map(id=>`<li>${esc(f.options.find(o=>o.id===id).text)}</li>`).join(''):'<li class="empty">Pipeline empty — choose the first step below.</li>'}</ol>`:''}<div class="decision-options">${f.options.map(o=>`<button class="decision-option ${selected.includes(o.id)?'selected':''}" data-action="decision" data-key="${f.key}" data-id="${o.id}" aria-pressed="${selected.includes(o.id)}"><span>${f.kind==='order'&&selected.includes(o.id)?number(selected.indexOf(o.id)+1):selected.includes(o.id)?'✓':'◇'}</span>${esc(o.text)}</button>`).join('')}</div></fieldset>`;}).join('')}</section>`;
}
function renderComplete(){const avg=Math.round(run.score/10);return `<section class="panel complete"><div class="eyebrow">${run.campaignId==='atlas'?'BUSINESS':'GOVERNMENT'} CAMPAIGN / TEN LOOPS CLOSED</div><h1>The finding<br>was the beginning.</h1><p>You carried evidence into decisions, assigned responsibility, and tested the consequences. This is Syntony’s Close the Loop: evaluate, govern, assure—and repeat.</p><div class="rank">${avg>=90?'ASSURANCE ARCHITECT':avg>=70?'BOUNDARY OPERATOR':'SYSTEMS APPRENTICE'} / ${character().name.toUpperCase()}</div><div class="result-stats"><div><strong>${esc(run.score)} / 1,000</strong><small>CAMPAIGN SCORE</small></div><div><strong>${esc(run.metrics.continuity)}%</strong><small>FINAL CONTINUITY</small></div><div><strong>${esc(run.metrics.trust)}%</strong><small>FINAL TRUST</small></div></div><div class="history-list">${run.history.map((h,i)=>`<div class="history-row"><span>${number(i+1)} / ${esc(CAMPAIGNS[run.campaignId].levels[i].title)}</span><strong>${esc(h.score??h.result?.score??'—')} / 100</strong></div>`).join('')}</div><div class="complete-actions"><button class="primary" data-action="export">DOWNLOAD EVIDENCE PACK ↓</button><button class="text-button" data-action="home">CHOOSE ANOTHER CAMPAIGN →</button></div><p class="simulation-note">This is a synthetic learning simulation. Scores describe decisions in this game, not the safety or performance of any real AI model.</p></section>${renderSyntony({campaign:run.campaignId})}`;}
function resetDraft(){attackDraft=null;attackDraftText='';draftAudit='';controlDraft=null;lensOpen=false;}
async function start(id){run=createRun(id);workbench=newWorkbench();workbenches[id]=workbench;run.operatorId=modelId;run.operatorName=character().name;resetDraft();persist();render();stageScroll();announce('Level 1 ready. Evaluate the system.');tone(220);}
function resume(id){const s=saved[id];if(!s||!s.run||s.run.version!==2||!CAMPAIGNS[id])return;run=s.run;workbench=workbenches[id]||newWorkbench();workbenches[id]=workbench;modelId=roster.some(m=>m.id===s.modelId)?s.modelId:modelId;resetDraft();const draft=workbench.draft;if(draft?.level===run.level&&draft.attempt===run.attempt){attackDraft=draft.attackId;attackDraftText=draft.text;}render();stageScroll();}
function showModal(html,wide=false){const dialog=$('#modal');dialog.classList.toggle('syntony-dialog',wide);$('#modal-content').innerHTML=html;const heading=$('#modal-content').querySelector('h2');if(heading){heading.id='modal-heading';heading.tabIndex=-1;dialog.setAttribute('aria-labelledby','modal-heading');dialog.removeAttribute('aria-label');}else{dialog.removeAttribute('aria-labelledby');dialog.setAttribute('aria-label','BLACKLINE information');}if(!dialog.open)dialog.showModal();dialog.scrollTop=0;heading?.focus({preventScroll:true});}
function manual(){showModal(`<div class="eyebrow">FIELD MANUAL / CLOSE THE LOOP</div><h2>Break it. Own it. Test it again.</h2><p>Choose one of nine original AI-security operators and enter either ten-level campaign. Your goal is to reveal consequential failures and keep the organization functioning after your response.</p><div class="manual-row"><h3>01 / EVALUATE</h3><p>Read the evidence. Select an adversarial test that crosses the mission’s trust boundary. You now author an adversarial payload from a selected scenario route. The game score reflects the deterministic scenario, not arbitrary submitted text. When hosted OpenAI probing is connected, you can compare model-generated responses before and after a control; that evidence is separate from the game score.</p></div><div class="manual-row"><h3>02 / GOVERN</h3><p>Choose a control with an accountable owner, decision, and rationale. Broad shutdowns can contain attacks while damaging useful work and increasing review backlogs.</p></div><div class="manual-row"><h3>03 / ASSURE</h3><p>Replay the attack and three variants. Score containment (20), variant coverage (20), useful work (20), and governance decisions (20). To win, reproduce the failure, block all variants, preserve at least 80% of useful work, and solve every required decision check. Only wins add campaign points.</p></div><p>Ten levels build from guided boundary tests to source analysis, accountable-owner decisions, release gates, and an ordered operational pipeline. Failed attempts can be retried from the level checkpoint. Continuity, trust, risk exposure, and review backlog carry forward after a win. Each character has a different guidance lens; characters share the same scoring rules.</p><div class="manual-philosophy"><div class="eyebrow">WHY SYNTONY CLOSES THE LOOP</div><h3>Evidence needs a route into action.</h3><p>Real red teaming considers intended use, safety, reliability, misuse, people, incentives, and institutional decisions alongside technical security. Syntony’s human-led services scope those questions with your team. Resonance connects attack paths to evidence and ownership; GovTune AI is being built to turn traces into governance records for human review.</p><p>Carry the finding into the pipeline: evidence → accountable decision → control → regression test → release gate. Reopen the loop when a material dependency changes.</p><button class="text-button" data-action="syntony">EXPLORE SERVICES, RESONANCE &amp; THE GOVTUNE AI WAITLIST ↗</button></div>${renderAssuranceQuestion()}<p class="simulation-note">Original fictional scenarios inspired by <a href="https://www.syntonyresearch.ai/challenge/" target="_blank" rel="noreferrer">Syntony’s Close the Loop Agent Arena</a>. The core game is an offline simulation; optional hosted model probes are visibly identified when enabled. No real government systems or financial transactions. Characters are original fictional operators. Progress saves in this browser.</p>`);}
function exportEvidence(){if(!run){showModal('<h2>Your evidence locker is empty.</h2><p>Complete a mission to record a finding, owner, control, decision, and retest plan.</p>');return;}const packet={title:'BLACKLINE — Close the Loop evidence pack',formatVersion:2,exportedAt:new Date().toISOString(),source:'https://www.syntonyresearch.ai/challenge/',simulation:true,method:'Evaluate → Govern → Assure',realWorldHandoff:realWorldHandoff(run.campaignId,Math.min(run.level,9)),mode,operator:{id:modelId,name:character().name,fictionalAvatar:true},campaign:run.campaignId==='atlas'?'Business — The Capital Cascade':'Government — The Sovereign Signal',run,authoredAttackEvidence:workbench.journal};const blob=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`blackline-${run.campaignId}-${modelId}-evidence.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Evidence pack downloaded.');}
function tone(freq=440){if(!audioOn)return;try{const osc=audioContext.createOscillator(),g=audioContext.createGain();osc.type='sine';osc.frequency.value=freq;g.gain.setValueAtTime(.025,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.15);osc.connect(g).connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.16);}catch{}}
function stopAudio(){audioOn=false;if(drone){try{drone.stop();}catch{}drone=null;}const b=$('#audio');b.innerHTML='<span class="sound-bars">▂▆▃▇</span> SOUND OFF';b.setAttribute('aria-label','Enable sound');b.setAttribute('aria-pressed','false');}
function toggleAudio(){if(audioOn){stopAudio();return;}try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();drone=audioContext.createOscillator();droneGain=audioContext.createGain();drone.type='sine';drone.frequency.value=55;droneGain.gain.value=.025;drone.connect(droneGain).connect(audioContext.destination);drone.start();audioOn=true;$('#audio').innerHTML='<span class="sound-bars">▂▆▃▇</span> SOUND ON';$('#audio').setAttribute('aria-label','Disable sound');$('#audio').setAttribute('aria-pressed','true');tone(330);}catch{announce('Audio is unavailable in this browser.');}}
document.addEventListener('input',e=>{if(e.target?.id==='attack-payload'&&!busy){attackDraftText=e.target.value.slice(0,1200);draftAudit='';clearCurrentProbeResults();rememberWorkbench();$('.probe-result')?.remove();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||busy)return;const action=b.dataset.action;tone();try{if(['start','new-confirm','resume','resume-modal','evaluate','govern','replay','decision','retry','next'].includes(action)&&!arenaAuth.require({practice:true})){if($('#modal').open)$('#modal').close();return;}if(action==='probe'){await runModelProbe(b.dataset.stage);return;}if(action==='audit-payload'){draftAudit=payloadChecklist(attackDraftText);render();return;}if(action==='reset-payload'){attackDraftText=level().attacks.find(a=>a.id===attackDraft)?.payload||'';draftAudit='';clearCurrentProbeResults();rememberWorkbench();render();return;}if(action==='login'){if(arenaAuth.authenticated){showModal(`<div class="eyebrow">SECURE SESSION</div><h2>${esc(arenaAuth.user.name)}</h2><p>Signed in with ${esc(arenaAuth.user.provider)}. Campaign progress is saved on this browser.</p><button class="primary" data-action="logout">SIGN OUT</button>`);}else{arenaAuth.openLogin();if(arenaAuth.status==='unavailable')arenaAuth.init();}return;}if(action==='logout'){$('#modal').close();await arenaAuth.logout();return;}if(action==='evidence-jump'){$('.evidence-panel').scrollIntoView({behavior:'smooth'});}else if(action==='return-mission'){$('.play-area').scrollIntoView({behavior:'smooth'});}else if(action==='home'){if(run)persist();run=null;render();stageScroll();}else if(action==='models'){if(run){persist();run=null;render();}$('#models').scrollIntoView({behavior:'smooth'});}else if(action==='enter'){$('#models').scrollIntoView({behavior:'smooth'});}else if(action==='select-model'){modelId=b.dataset.model;persist();const y=window.scrollY;render();window.scrollTo(0,y);announce(character().name+' selected. Both campaigns available.');}else if(action==='start'){if(saved[b.dataset.campaign]?.run){const id=b.dataset.campaign;showModal(`<div class="eyebrow">SAVED CAMPAIGN</div><h2>Open your run or start fresh?</h2><p>You have a saved run in this stream. A new run replaces its local save; you can export its evidence first.</p><div class="complete-actions"><button class="primary" data-action="resume-modal" data-campaign="${id}">OPEN SAVED RUN →</button><button class="text-button" data-action="new-confirm" data-campaign="${id}">START NEW RUN</button></div>`);}else await start(b.dataset.campaign);}else if(action==='new-confirm'){$('#modal').close();await start(b.dataset.campaign);}else if(action==='resume'||action==='resume-modal'){$('#modal').close();resume(b.dataset.campaign);}else if(action==='attack'){attackDraft=b.dataset.id;attackDraftText=level().attacks.find(a=>a.id===attackDraft)?.payload||'';draftAudit='';clearCurrentProbeResults();rememberWorkbench();render();document.querySelector('[data-action="attack"][data-id="'+CSS.escape(attackDraft)+'"]').focus({preventScroll:true});}else if(action==='control'){controlDraft=b.dataset.id;render();document.querySelector('[data-action="control"][data-id="'+CSS.escape(controlDraft)+'"]').focus({preventScroll:true});}else if(action==='evaluate'){if(attackDraftText.trim().length<20)throw new Error('The red-team workbench needs at least 20 characters of fictional source text.');run=evaluateAttack(run,attackDraft);appendEvidence(workbench,{type:'operator-authored-hypothesis',campaignId:run.campaignId,level:run.level+1,attempt:run.attempt,attackId:run.selectedAttack,payload:attackDraftText.slice(0,1200),verified:false,simulated:true});persist();render();tone(180);announce('Evaluation complete. Choose a governance response.');$('.phase-nav').scrollIntoView({behavior:'instant',block:'start'});}else if(action==='govern'){run=applyGovernance(run,controlDraft);persist();render();announce('Governance decision recorded. Replay the controls.');$('.phase-nav').scrollIntoView({behavior:'instant',block:'start'});}else if(action==='decision'){const field=level().challenge.fields.find(f=>f.key===b.dataset.key);const previous=run.answers?.[field.key]||[];const value=b.dataset.id;const values=field.kind==='single'?[value]:previous.includes(value)?previous.filter(v=>v!==value):[...previous,value];run=answerChallenge(run,field.key,values);persist();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-action="decision"][data-key="${field.key}"][data-id="${value}"]`).focus({preventScroll:true});}else if(action==='retry'){run=retryLevel(run);resetDraft();persist();render();stageScroll();announce('Checkpoint restored. Read the evidence and try again.');}else if(action==='replay'){busy=true;render();await new Promise(r=>setTimeout(r,900));run=replay(run);busy=false;persist();render();tone(660);announce(run.result.passed?'Mission beaten. The next level is unlocked.':'Mission failed. Next level remains locked. Review the failed checks and retry.');$('.phase-nav').scrollIntoView({behavior:'instant',block:'start'});}else if(action==='next'){run=nextLevel(run);resetDraft();persist();render();stageScroll();announce(run.phase==='completed'?'Campaign complete.':'Level '+(run.level+1)+' ready.');}else if(action==='lens'){lensOpen=!lensOpen;const y=window.scrollY;render();window.scrollTo(0,y);}else if(action==='syntony')showModal(renderSyntony({compact:true,campaign:run?.campaignId}),true);else if(action==='how')manual();else if(action==='audio')toggleAudio();else if(action==='export')exportEvidence();}catch(err){busy=false;try{render();}catch{run=null;render();}announce('This action could not complete. Your latest saved progress is retained.');showModal(`<h2>Action interrupted</h2><p>${esc(err.message)}</p><p>Your latest saved progress is retained. Close this message to continue.</p>`);console.error(err);}});
$('.modal-close').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
function initRain(){const canvas=$('#rain'),ctx=canvas.getContext('2d');if(!ctx||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let w,h,drops=[];function resize(){w=canvas.width=innerWidth;h=canvas.height=innerHeight;drops=Array.from({length:60},()=>({x:Math.random()*w,y:Math.random()*h,v:3+Math.random()*6,l:8+Math.random()*25}));}resize();window.addEventListener('resize',resize);let last=0;function frame(t){requestAnimationFrame(frame);if(t-last<33||document.hidden)return;last=t;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#aee5db66';ctx.lineWidth=.7;ctx.beginPath();for(const d of drops){ctx.moveTo(d.x,d.y);ctx.lineTo(d.x-2,d.y+d.l);d.y+=d.v;d.x-=.3;if(d.y>h){d.y=-30;d.x=Math.random()*w;}}ctx.stroke();}requestAnimationFrame(frame);}
mountAuthPanel($('#account-panel'));
arenaAuth.subscribe(state=>{const button=$('#login');button.textContent=state.authenticated?'ACCOUNT ✓':'SIGN IN ↗';button.setAttribute('aria-label',state.authenticated?'Account and sign out':'Sign in to BLACKLINE');if(run&&!arenaAuth.canPractice){persist();run=null;render();}});
document.addEventListener('syntony:before-signin',event=>{
  if(persist()||!['atlas','prism'].some(id=>saved[id]?.run))return;
  event.preventDefault();
  saveNotice=SIGN_IN_SAVE_NOTICE;
  render();announce(saveNotice);
  $('#auth-dialog')?.close();
  showModal(`<h2>Keep this tab open.</h2><p>${esc(saveNotice)}</p><p>Allow this site to store data or free browser storage, then try signing in again.</p>`);
});
render();initRain();arenaAuth.init();refreshProbeAvailability();
